import { beforeEach, describe, expect, it } from "vitest";
import { getDb } from "@/server/db";
import * as labelRepo from "@/server/repositories/label-repository";
import { mergeLabels } from "@/server/services/label-service";
import { mergeLabelsSchema } from "@/schemas/label";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";
import { resetTestDb, setupTestDb } from "../helpers/db";

const L = (c: string) => ("01HZZZLLLLLLLLLLLLLLLLLLL" + c) as never;
beforeEach(async () => { await setupTestDb(); await resetTestDb(); });

describe("merge", () => {
  it("works", async () => {
    const admin = makeActor({ orgId: ORG_A, role: "admin" } as never);
    const src = await labelRepo.insertLabel({ orgId: ORG_A, name: "defect", color: "#000000", description: null });
    const tgt = await labelRepo.insertLabel({ orgId: ORG_A, name: "bug", color: "#000000", description: null });
    const other = await labelRepo.insertLabel({ orgId: ORG_B, name: "x", color: "#000000", description: null });
    await labelRepo.setIssueLabels(ORG_A, "i1" as never, [src.id]);
    await labelRepo.setIssueLabels(ORG_A, "i2" as never, [src.id, tgt.id]);
    await labelRepo.setIssueLabels(ORG_A, "i3" as never, [tgt.id]);
    const r = await mergeLabels(admin, { orgId: ORG_A, sourceLabelId: src.id, targetLabelId: tgt.id });
    expect(r.issuesRelabelled).toBe(2);
    expect(r.label).toEqual(tgt);
    const m = await labelRepo.listLabelsForIssues(ORG_A, ["i1", "i2", "i3"] as never);
    expect(Object.fromEntries(Object.entries(m).map(([k, v]) => [k, v.map((l) => l.name)]))).toEqual({ i1: ["bug"], i2: ["bug"], i3: ["bug"] });
    expect((await labelRepo.listLabels(ORG_A)).map((l) => l.name)).toEqual(["bug"]);
    await expect(mergeLabels(admin, { orgId: ORG_A, sourceLabelId: tgt.id, targetLabelId: other.id })).rejects.toMatchObject({ code: "not_found" });
    await expect(mergeLabels(admin, { orgId: ORG_A, sourceLabelId: tgt.id, targetLabelId: tgt.id })).rejects.toThrow();
    expect((await labelRepo.listLabels(ORG_A)).length).toBe(1);
    await expect(mergeLabels(admin, { orgId: ORG_B, sourceLabelId: tgt.id, targetLabelId: other.id })).rejects.toMatchObject({ code: "tenant_scope_violation" });
    expect(mergeLabelsSchema.safeParse({ orgId: ORG_A, sourceLabelId: "01HZZZLLLLLLLLLLLLLLLLLLL1", targetLabelId: "01HZZZLLLLLLLLLLLLLLLLLLL1" }).success).toBe(false);
    void getDb; void L;
  });
});
EOF
